% mathsmap-diagram-colours {"version":1,"kind":"graph","base":[],"semantic":[{"name":"quadraticBlue","hex":"268CFF","reason":"quadratic series"},{"name":"quarticRed","hex":"EF6068","reason":"quartic series"},{"name":"sexticGreen","hex":"4F9B63","reason":"sextic series"}],"reference":"PDF 43 Q6a; teacher PDF 15 Q6"}
\begin{tikzpicture}[x=1.3cm,y=0.65cm,font=\fontsize{10}{12}\selectfont]
\special{dvisvgm:raw <metadata data-graph-strokes="1"/>}
\definecolor{quadraticBlue}{HTML}{268CFF}
\definecolor{quarticRed}{HTML}{EF6068}
\definecolor{sexticGreen}{HTML}{4F9B63}
\path[use as bounding box] (-2.9,-0.8) rectangle (4.4,7.5);
\draw[black,line width=0.5pt,->] (-2.8,0)--(2.8,0) node[right] {$x$};
\draw[black,line width=0.5pt,->] (0,-0.5)--(0,7.2) node[above] {$y$};
\foreach \v in {-2,-1,1,2}{\draw[black,line width=0.4pt] (\v,-0.08)--(\v,0.08);\node[below,font=\fontsize{8.5}{10}\selectfont] at (\v,-0.08) {\special{dvisvgm:raw <g data-graph-text="tick">}$\v$\special{dvisvgm:raw </g>}};}
\foreach \v in {2,4,6}{\draw[black,line width=0.4pt] (-0.04,\v)--(0.04,\v);\node[left,font=\fontsize{8.5}{10}\selectfont] at (-0.04,\v) {\special{dvisvgm:raw <g data-graph-text="tick">}$\v$\special{dvisvgm:raw </g>}};}
\draw[quadraticBlue,line width=0.8pt,<->,domain=-2.6:2.6,samples=101] plot (\x,{\x^2});
\draw[quarticRed,line width=0.8pt,dashed,<->,domain=-1.61:1.61,samples=101] plot (\x,{\x^4});
\draw[sexticGreen,line width=0.8pt,dotted,<->,domain=-1.37:1.37,samples=101] plot (\x,{\x^6});
\foreach \x in {-1,1}{\fill[black] (\x,1) circle[radius=0.045];}
\node[right,text=quadraticBlue] at (2.65,6.4) {$y=x^2$};
\node[right,text=quarticRed] at (2.65,5.3) {$y=x^4$};
\node[right,text=sexticGreen] at (2.65,4.2) {$y=x^6$};
\end{tikzpicture}
